try {
  console.log('🛠️ Launching Firefox...');
  driver = await new Builder()
    .forBrowser('firefox')
    .setFirefoxOptions(options)
    .setFirefoxService(service)
    .build();
  console.log('✅ Firefox launched.');
  await driver.get('https://www.google.com');
  await driver.manage().deleteCookie("CONSENT");
  await driver.manage().addCookie({
    name: "CONSENT",
    value: `YES+${new Date().toISOString().slice(0,10).replace(/-/g,"")}-RC1`
  });
  await driver.navigate().refresh();
  const input = await driver.wait(until.elementLocated(By.css('input[name="q"]')), 10000);
  await input.sendKeys('selenium', Key.ENTER);
  await driver.wait(until.titleContains('selenium'), 10000);
  const title = await driver.getTitle();
  assert.ok(title.toLowerCase().includes('selenium'));
  console.log('✅ Test passed');
} catch (err) {
  console.error('❌ Test failed:', err);
  throw err;
} finally {
  if (driver) await driver.quit();
}
